package com.wethaq.app

import android.content.Context
import android.graphics.Color
import android.graphics.Typeface
import android.os.Bundle
import android.text.InputType
import android.view.Gravity
import android.view.View
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import okhttp3.*
import org.json.JSONObject
import java.security.SecureRandom
import java.util.Calendar
import java.util.concurrent.TimeUnit

class MainActivity : AppCompatActivity() {
    private val prefs by lazy { getSharedPreferences("wethaq_v5", Context.MODE_PRIVATE) }
    private val http = OkHttpClient.Builder().connectTimeout(8, TimeUnit.SECONDS).readTimeout(12, TimeUnit.SECONDS).build()
    private val teal = Color.rgb(0,137,123); private val navy = Color.rgb(17,38,54); private val bg = Color.rgb(247,249,250); private val line = Color.rgb(220,228,231); private val gray = Color.rgb(98,112,122)
    private val apiBase = "https://wethaq-backend.onrender.com"
    private var socket: WebSocket? = null; private var messagesLayout: LinearLayout? = null; private var messagesScroll: ScrollView? = null
    private val myName get() = prefs.getString("name","") ?: ""; private val myYear get() = prefs.getInt("year",0); private val myId get() = prefs.getString("id","") ?: ""; private val token get() = prefs.getString("token","") ?: ""

    override fun onCreate(state: Bundle?) { super.onCreate(state); window.statusBarColor=Color.WHITE; window.navigationBarColor=Color.WHITE; window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR; if(myName.isBlank()||myId.isBlank()) welcome() else home() }
    override fun onDestroy(){ socket?.close(1000,"closed"); super.onDestroy() }
    private fun dp(n:Int)=(n*resources.displayMetrics.density).toInt()
    private fun bg(c:Int,r:Int=18,s:Int?=null)=android.graphics.drawable.GradientDrawable().apply{setColor(c);cornerRadius=dp(r).toFloat();if(s!=null)setStroke(dp(1),s)}
    private fun root()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(::bg.get().let{Color.rgb(247,249,250)});layoutDirection=View.LAYOUT_DIRECTION_RTL}
    private fun label(s:String,size:Float=16f,c:Int=navy,b:Boolean=false)=TextView(this).apply{text=s;textSize=size;setTextColor(c);gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;textAlignment=View.TEXT_ALIGNMENT_VIEW_START;if(b)typeface=Typeface.DEFAULT_BOLD}
    private fun center(s:String,size:Float=16f,c:Int=navy,b:Boolean=false)=label(s,size,c,b).apply{gravity=Gravity.CENTER;textAlignment=View.TEXT_ALIGNMENT_CENTER}
    private fun button(s:String,a:()->Unit,c:Int=teal)=TextView(this).apply{text=s;textSize=15f;setTextColor(Color.WHITE);gravity=Gravity.CENTER;typeface=Typeface.DEFAULT_BOLD;background=bg(c,16);setPadding(dp(12),dp(8),dp(12),dp(8));setOnClickListener{a()}}
    private fun outline(s:String,a:()->Unit)=TextView(this).apply{text=s;textSize=14f;setTextColor(navy);gravity=Gravity.CENTER;typeface=Typeface.DEFAULT_BOLD;background=bg(Color.WHITE,16,line);setOnClickListener{a()}}
    private fun edit(h:String,num:Boolean=false)=EditText(this).apply{hint=h;textSize=16f;setTextColor(navy);setHintTextColor(gray);setSingleLine(true);inputType=if(num)InputType.TYPE_CLASS_NUMBER else InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_FLAG_CAP_SENTENCES;background=bg(Color.WHITE,16,line);setPadding(dp(15),0,dp(15),0);gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;textAlignment=View.TEXT_ALIGNMENT_VIEW_START}
    private fun add(p:LinearLayout,v:View,h:Int=-2,w:Float=0f,m:Int=0){val lp=LinearLayout.LayoutParams(-1,if(h==-2)-2 else dp(h),w);if(m>0)lp.setMargins(dp(m),dp(m),dp(m),dp(m));p.addView(v,lp)}
    private fun avatar(size:Int=70)=ImageView(this).apply{setImageResource(R.drawable.profile_photo);scaleType=ImageView.ScaleType.CENTER_CROP;background=bg(Color.WHITE,100,teal);setPadding(dp(2),dp(2),dp(2),dp(2));layoutParams=LinearLayout.LayoutParams(dp(size),dp(size));contentDescription="صورة مؤسس وَثاق"}
    private fun header(t:String,s:String="",back:(()->Unit)?=null)=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(14),dp(8),dp(14),dp(8));val x=LinearLayout(this@MainActivity).apply{orientation=LinearLayout.VERTICAL};add(x,label(t,22f,navy,true),30);if(s.isNotBlank())add(x,label(s,12f,gray),22);add(this,x,0,1f);if(back!=null)addView(outline("رجوع",back),LinearLayout.LayoutParams(dp(72),dp(44)))}
    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_SHORT).show()

    private fun welcome(){val r=root();val sc=ScrollView(this);val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_HORIZONTAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(22),dp(28),dp(22),dp(28))};add(c,avatar(128),128,0f,4);add(c,center("وَثاق",40f,navy,true),54);add(c,center("تواصل عربي مستقل",18f,gray,true),32);add(c,center("هويتك باسمك وسنة ميلادك، بلا كلمة مرور",14f,gray),42);val f=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;background=bg(Color.WHITE,20,line);setPadding(dp(10),dp(10),dp(10),dp(10))};f.addView(avatar(60));add(f,label("المؤسس\nحاتم حسين الحاج رمضان",14f,navy,true),0,1f,10);add(c,f,84,0f,8);add(c,button("تسجيل الدخول",{login()}),58,0f,5);add(c,button("إنشاء هوية جديدة",{register()},Color.rgb(28,71,91)),58,0f,5);sc.addView(c);add(r,sc,0,1f);setContentView(r)}

    private fun login(){identityForm("تسجيل الدخول","الاسم الثلاثي + سنة الميلاد فقط","دخول إلى وَثاق"){n,y->if(myName==n&&myYear==y&&myId.isNotBlank()){home();return@identityForm};request("POST","/api/login",JSONObject().put("name",n).put("birthYear",y).put("deviceKey",deviceKey())){ok,b->runOnUiThread{if(ok){saveServer(b);home()}else showLoginFailure(n,y)}}}}
    private fun showLoginFailure(n:String,y:Int){val r=root();val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(22),dp(20),dp(22),dp(20))};add(c,header("تعذر تسجيل الدخول","الهوية غير موجودة على الخادم",{welcome()}));add(c,center("لا توجد كلمة مرور في وَثاق.",16f,navy,true),55,0f,8);add(c,button("إنشاء هذه الهوية",{saveLocal(n,y);home()}),56,0f,5);add(c,outline("العودة",{welcome()}),52,0f,5);add(r,c,0,1f);setContentView(r)}
    private fun register(){identityForm("إنشاء هوية وَثاق","لا كلمة مرور ولا رقم هاتف","إنشاء المعرف والدخول"){n,y->createIdentity(n,y)}}
    private fun identityForm(title:String,sub:String,action:String,submit:(String,Int)->Unit){val r=root();val sc=ScrollView(this);val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(20),dp(10),dp(20),dp(24))};add(c,header(title,sub,{welcome()}));add(c,avatar(96),96,0f,8);add(c,label("الاسم الثلاثي",14f,navy,true),30,0f,2);val n=edit("مثال: حاتم حسين الحاج رمضان");add(c,n,56,0f,2);add(c,label("سنة الميلاد",14f,navy,true),30,0f,6);val y=edit("مثال: 1995",true);add(c,y,56,0f,2);val id=center("سيظهر معرفك هنا",14f,teal,true);id.background=bg(Color.WHITE,16,line);add(c,id,58,0f,10);val update={val a=n.text.toString().trim();val b=y.text.toString().trim().toIntOrNull();id.text=if(a.isBlank()||b==null)"سيظهر معرفك هنا" else "@${makeId(a,b)}"};n.setOnFocusChangeListener{_,_->update()};y.setOnFocusChangeListener{_,_->update()};add(c,center("المعرف هو وسيلة التواصل مع الآخرين.",12f,gray),42,0f,4);add(c,button(action){val a=n.text.toString().trim();val b=y.text.toString().trim().toIntOrNull();val words=a.split(Regex("\\s+")).filter{it.isNotBlank()};val max=Calendar.getInstance().get(Calendar.YEAR);if(words.size<3){toast("اكتب الاسم الثلاثي");return@button};if(b==null||b !in 1900..max){toast("سنة الميلاد غير صحيحة");return@button};submit(a,b)},58,0f,6);add(c,outline("إلغاء",{welcome()}),50,0f,3);sc.addView(c);add(r,sc,0,1f);setContentView(r)}

    private fun createIdentity(n:String,y:Int){request("POST","/api/identity",JSONObject().put("name",n).put("birthYear",y).put("deviceKey",deviceKey())){ok,b->runOnUiThread{if(ok){saveServer(b)}else saveLocal(n,y);home()}}}
    private fun saveLocal(n:String,y:Int){prefs.edit().putString("name",n).putInt("year",y).putString("id",makeId(n,y)).remove("token").apply()}
    private fun saveServer(b:JSONObject){val u=b.optJSONObject("user")?:return;prefs.edit().putString("token",b.optString("token")).putString("name",u.optString("name")).putInt("year",u.optInt("birth_year")).putString("id",u.optString("wethaq_id")).putString("server_id",u.optString("id")).apply()}
    private fun deviceKey():String{val o=prefs.getString("device","")?:"";if(o.length>=24)return o;val b=ByteArray(24);SecureRandom().nextBytes(b);val k=b.joinToString(""){String.format("%02x",it)};prefs.edit().putString("device",k).apply();return k}
    private fun makeId(name:String,year:Int):String{val known=mapOf("حاتم" to "Hatem","حسين" to "Hussin","الحاج" to "Al_Haj","رمضان" to "Ramadan","محمد" to "Mohammad","أحمد" to "Ahmad","علي" to "Ali","خالد" to "Khaled","سارة" to "Sara","نور" to "Nour","هدى" to "Huda","وسام" to "Wisam","يامن" to "Yamen","هشام" to "Hisham","أيمن" to "Ayman","حسام" to "Hossam");val map=mapOf('ا' to "a",'أ' to "a",'إ' to "i",'آ' to "a",'ب' to "b",'ت' to "t",'ث' to "th",'ج' to "j",'ح' to "h",'خ' to "kh",'د' to "d",'ذ' to "dh",'ر' to "r",'ز' to "z",'س' to "s",'ش' to "sh",'ص' to "s",'ض' to "d",'ط' to "t",'ظ' to "z",'ع' to "a",'غ' to "gh",'ف' to "f",'ق' to "q",'ك' to "k",'ل' to "l",'م' to "m",'ن' to "n",'ه' to "h",'و' to "w",'ي' to "y",'ى' to "a",'ة' to "h");return(name.replace("ـ","").split(Regex("[\\s،,]+" )).filter{it.isNotBlank()}.map{w->known[w]?:w.map{ch->map[ch]?:if(ch.isLetterOrDigit())ch.toString()else""}.joinToString("").replaceFirstChar{it.uppercase()}}.filter{it.isNotBlank()}.joinToString("_")+year).replace(Regex("[^A-Za-z0-9_]"),"_")}

    private fun home(){val r=root();add(r,header("وَثاق","مرحبًا $myName"));val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(14),dp(8),dp(14),dp(14))};val p=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;background=bg(Color.WHITE,20,line);setPadding(dp(10),dp(10),dp(10),dp(10))};p.addView(avatar(58));add(p,label("$myName\n@$myId",13f,navy,true),0,1f,10);add(c,p,82,0f,4);val q=edit("ابحث بالاسم أو معرف وَثاق");add(c,q,54,0f,4);add(c,button("بحث عن شخص",{search(q.text.toString())}),54,0f,4);add(c,button("المحادثات",{conversations()},Color.rgb(28,71,91)),54,0f,4);add(c,button("ملفي ومعرفي",{profile()},Color.rgb(70,90,100)),54,0f,4);add(c,outline("تسجيل الخروج",{prefs.edit().clear().apply();welcome()}),50,0f,4);add(r,c,0,1f);setContentView(r);connectSocket()}
    private fun profile(){val r=root();val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(20),dp(12),dp(20),dp(20))};add(c,header("ملفي","هوية وَثاق",{home()}));add(c,avatar(110),110,0f,12);add(c,center(myName,22f,navy,true),38);add(c,center("@$myId",15f,teal,true),42);add(c,button("نسخ المعرف",{(getSystemService(Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager).setPrimaryClip(android.content.ClipData.newPlainText("Wethaq ID",myId));toast("تم نسخ المعرف")}),54,0f,8);add(c,center("المؤسس\nحاتم حسين الحاج رمضان",14f,gray),60,0f,12);add(r,c,0,1f);setContentView(r)}

    private fun search(q:String){if(q.trim().length<2){toast("اكتب اسمًا أو معرفًا للبحث");return};request("GET","/api/search?q=${java.net.URLEncoder.encode(q.trim(),"UTF-8")}",null){ok,b->runOnUiThread{if(ok)renderSearch(b)else toast("البحث يحتاج اتصالًا بالخادم")}}}
    private fun renderSearch(b:JSONObject){val r=root();val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(14),dp(8),dp(14),dp(14))};add(c,header("نتائج البحث","الأشخاص الذين يطابقون بحثك",{home()}));val users=b.optJSONArray("users")?:org.json.JSONArray();if(users.length()==0)add(c,center("لم يتم العثور على شخص.",14f,gray),100) else for(i in 0 until users.length()){val u=users.optJSONObject(i)?:continue;val id=u.optString("wethaq_id");val name=u.optString("name");val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;background=bg(Color.WHITE,18,line);setPadding(dp(10),dp(8),dp(10),dp(8))};row.addView(avatar(52));add(row,label("$name\n@$id",13f,navy,true),0,1f,10);row.addView(button("محادثة",{openChat(id,name)}),LinearLayout.LayoutParams(dp(82),dp(46)));add(c,row,70,0f,4)};add(r,c,0,1f);setContentView(r)}
    private fun conversations(){val r=root();val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(14),dp(8),dp(14),dp(14))};add(c,header("المحادثات","محادثاتك الأخيرة",{home()}));val ids=prefs.getStringSet("chats",emptySet())?:emptySet();if(ids.isEmpty())add(c,center("لا توجد محادثات بعد.\nابحث عن شخص ثم اضغط «محادثة».",15f,gray),120) else ids.forEach{id->val name=prefs.getString("chat_name_$id",id)?:id;val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;background=bg(Color.WHITE,18,line);setPadding(dp(10),dp(8),dp(10),dp(8));layoutDirection=View.LAYOUT_DIRECTION_RTL};row.addView(avatar(52));add(row,label("$name\n@$id",13f,navy,true),0,1f,10);add(c,row,68,0f,4);row.setOnClickListener{openChat(id,name)}};add(r,c,0,1f);setContentView(r)}

    private fun openChat(id:String,name:String){prefs.edit().putStringSet("chats",(prefs.getStringSet("chats",emptySet())?:emptySet())+id).putString("chat_name_$id",name).apply();val r=root();add(r,header(name,"@$id",{conversations()}));messagesScroll=ScrollView(this);messagesLayout=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(12),dp(8),dp(12),dp(8))};messagesScroll!!.addView(messagesLayout);add(r,messagesScroll!!,0,1f);val bar=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutDirection=View.LAYOUT_DIRECTION_RTL;setPadding(dp(8),dp(8),dp(8),dp(8))};val input=edit("اكتب رسالة...");add(bar,input,52,1f,2);add(bar,button("إرسال",{val m=input.text.toString().trim();if(m.isNotEmpty()){addMessage(m,true);input.setText("");sendMessage(id,m)}}),52,0f,2);add(r,bar,68);setContentView(r);loadMessages(id)}
    private fun addMessage(text:String,mine:Boolean){val v=TextView(this).apply{this.text=text;textSize=15f;setTextColor(if(mine)Color.WHITE else navy);setPadding(dp(14),dp(9),dp(14),dp(9));background=bg(if(mine)teal else Color.WHITE,18,if(mine)null else line);layoutDirection=View.LAYOUT_DIRECTION_RTL};val lp=LinearLayout.LayoutParams(dp(280),-2);lp.gravity=if(mine)Gravity.START else Gravity.END;lp.setMargins(dp(4),dp(4),dp(4),dp(4));messagesLayout?.addView(v,lp);messagesScroll?.post{messagesScroll?.fullScroll(View.FOCUS_DOWN)}}
    private fun loadMessages(id:String){if(token.isBlank())return;request("GET","/api/messages/${java.net.URLEncoder.encode(id,"UTF-8")}",null){ok,b->runOnUiThread{if(ok){val a=b.optJSONArray("messages")?:return@runOnUiThread;for(i in 0 until a.length()){val m=a.optJSONObject(i)?:continue;addMessage(m.optString("body"),m.optInt("sender_id")==prefs.getString("server_id","0")?.toIntOrNull())}}}}}
    private fun sendMessage(to:String,text:String){if(token.isBlank()){toast("تم عرض الرسالة محليًا؛ يلزم اتصال بالخادم لإرسالها للشخص الآخر");return};request("POST","/api/messages",JSONObject().put("to",to).put("body",text)){ok,_->if(!ok)runOnUiThread{toast("تعذر إرسال الرسالة، حاول عند توفر الاتصال")}}}
    private fun connectSocket(){if(token.isBlank())return;val rq=Request.Builder().url(apiBase.replace("https://","wss://")+"/ws?token=$token").build();socket?.close(1000,"replace");socket=http.newWebSocket(rq,object:WebSocketListener(){override fun onMessage(ws:WebSocket,text:String){try{val o=JSONObject(text);if(o.optString("type")=="message")runOnUiThread{val m=o.optJSONObject("message");if(m!=null)addMessage(m.optString("body"),false)}}catch(_:Exception){}}})}
    private fun request(method:String,path:String,json:JSONObject?=null,done:(Boolean,JSONObject)->Unit){Thread{try{val b=Request.Builder().url(apiBase+path);if(token.isNotBlank())b.addHeader("Authorization","Bearer $token");if(method=="POST")b.post((json?:JSONObject()).toString().toRequestBody("application/json; charset=utf-8"))else b.get();http.newCall(b.build()).execute().use{res->val raw=res.body?.string()?:("{}");done(res.isSuccessful,try{JSONObject(raw)}catch(_:Exception){JSONObject()})}}catch(_:Exception){done(false,JSONObject())}}.start()}
}
